const config = {
  "previewFeatures": [],
  "clientVersion": "7.6.0",
  "engineVersion": "75cbdc1eb7150937890ad5465d861175c6624711",
  "activeProvider": "postgresql",
  "inlineSchema": "// ─── Account Type Enum ────────────────────────────────────────────────────────\nenum AccountType {\n  ASSET\n  LIABILITY\n  EQUITY\n  REVENUE\n  EXPENSE\n}\n\n// ─── Journal Entry Status Enum ────────────────────────────────────────────────\nenum JournalEntryStatus {\n  DRAFT\n  POSTED\n}\n\n// ─── Reference Type Enum ───────────────────────────────────────────────────────\nenum ReferenceType {\n  INVOICE\n  INVOICE_CANCELLATION\n  PAYMENT\n  PAYMENT_CANCELLATION\n  EXPENSE\n  EXPENSE_CANCELLATION\n  OPENING_BALANCE\n  OPENING_BALANCE_CANCELLATION\n  STOCK_COUNT\n  STOCK_COUNT_CANCELLATION\n}\n\n// ─── Chart Of Accounts ───────────────────────────────────────────────────────\nmodel ChartOfAccount {\n  id         String      @id @default(uuid())\n  tenantId   String      @map(\"tenant_id\")\n  code       String\n  name       Json        @db.JsonB // LocalizedString: { ar: string; en?: string }\n  type       AccountType\n  parentId   String?     @map(\"parent_id\")\n  isActive   Boolean     @default(true) @map(\"is_active\")\n  isPostable Boolean     @default(true) @map(\"is_postable\")\n  isContra   Boolean     @default(false) @map(\"is_contra\")\n  deletedAt  DateTime?   @map(\"deleted_at\")\n  createdAt  DateTime    @default(now()) @map(\"created_at\")\n  updatedAt  DateTime    @updatedAt @map(\"updated_at\")\n\n  tenant                        Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  parent                        ChartOfAccount?             @relation(\"AccountHierarchy\", fields: [parentId], references: [id])\n  children                      ChartOfAccount[]            @relation(\"AccountHierarchy\")\n  journalLines                  JournalLine[]\n  expenseItems                  ExpenseItem[]               @relation(\"ExpenseItemAccount\")\n  // FinancialSetting back-relations (GL mapping)\n  defaultSalesFor               FinancialSetting[]          @relation(\"DefaultSalesAccount\")\n  defaultPurchaseFor            FinancialSetting[]          @relation(\"DefaultPurchaseAccount\")\n  defaultTaxFor                 FinancialSetting[]          @relation(\"DefaultTaxAccount\")\n  defaultReceivableFor          FinancialSetting[]          @relation(\"DefaultReceivableAccount\")\n  defaultPayableFor             FinancialSetting[]          @relation(\"DefaultPayableAccount\")\n  defaultInventoryFor           FinancialSetting[]          @relation(\"DefaultInventoryAccount\")\n  defaultCogsFor                FinancialSetting[]          @relation(\"DefaultCogsAccount\")\n  defaultInventoryAdjustmentFor FinancialSetting[]          @relation(\"DefaultInventoryAdjustmentAccount\")\n  defaultOpeningEquityFor       FinancialSetting[]          @relation(\"DefaultOpeningEquityAccount\")\n  defaultCashFor                FinancialSetting[]          @relation(\"DefaultCashAccount\")\n  defaultBankFor                FinancialSetting[]          @relation(\"DefaultBankAccount\")\n  // Party-level override back-relations\n  partyReceivables              Party[]                     @relation(\"PartyReceivableAccount\")\n  partyPayables                 Party[]                     @relation(\"PartyPayableAccount\")\n  openingBalanceSessionLines    OpeningBalanceSessionLine[]\n  // REMOVED: currentBalance Decimal (source of truth is JournalLine; balances computed on read)\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@index([parentId])\n  @@map(\"chart_of_accounts\")\n}\n\n// ─── Journal Entry ────────────────────────────────────────────────────────────\nmodel JournalEntry {\n  id             String             @id @default(uuid())\n  tenantId       String             @map(\"tenant_id\")\n  number         String\n  date           DateTime\n  fiscalPeriodId String             @map(\"fiscal_period_id\")\n  /// Branch derived from the source document at posting time, never chosen by\n  /// a human. Nullable in the DB for backfill safety + pre-#32 documents.\n  branchId       String?            @map(\"branch_id\")\n  referenceType  ReferenceType?     @map(\"reference_type\")\n  referenceId    String?            @map(\"reference_id\")\n  description    String?\n  status         JournalEntryStatus @default(DRAFT)\n  /// Exchange rate to tenant base currency locked at posting time.\n  exchangeRate   Decimal            @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  postedAt       DateTime?          @map(\"posted_at\")\n  reversalOfId   String?            @map(\"reversal_of_id\")\n  reversalDate   DateTime?          @map(\"reversal_date\")\n  createdBy      String             @map(\"created_by\")\n  createdAt      DateTime           @default(now()) @map(\"created_at\")\n  updatedAt      DateTime           @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  fiscalPeriod FiscalPeriod   @relation(fields: [fiscalPeriodId], references: [id])\n  branch       Branch?        @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  reversalOf   JournalEntry?  @relation(\"JournalReversals\", fields: [reversalOfId], references: [id])\n  reversedBy   JournalEntry[] @relation(\"JournalReversals\")\n  lines        JournalLine[]\n\n  @@unique([tenantId, number])\n  @@index([tenantId])\n  @@index([tenantId, branchId])\n  @@index([referenceType, referenceId])\n  @@map(\"journal_entries\")\n}\n\n// ─── Journal Line ─────────────────────────────────────────────────────────────\nmodel JournalLine {\n  id             String  @id @default(uuid())\n  tenantId       String  @map(\"tenant_id\")\n  journalEntryId String  @map(\"journal_entry_id\")\n  accountId      String  @map(\"account_id\")\n  partyId        String? @map(\"party_id\")\n  cashboxId      String? @map(\"cashbox_id\")\n  bankAccountId  String? @map(\"bank_account_id\")\n  currencyId     String? @map(\"currency_id\")\n  /// Transaction-currency amount; direction implied by debit/credit.\n  amount         Decimal @default(0) @db.Decimal(18, 4)\n  /// Locked exchange rate to base currency for this line.\n  exchangeRate   Decimal @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  debit          Decimal @default(0) @db.Decimal(18, 4)\n  credit         Decimal @default(0) @db.Decimal(18, 4)\n  description    String?\n  sortOrder      Int     @default(0) @map(\"sort_order\")\n\n  journalEntry JournalEntry   @relation(fields: [journalEntryId], references: [id], onDelete: Cascade)\n  account      ChartOfAccount @relation(fields: [accountId], references: [id])\n  party        Party?         @relation(\"JournalLineParty\", fields: [partyId], references: [id])\n  cashbox      Cashbox?       @relation(fields: [cashboxId], references: [id])\n  bankAccount  BankAccount?   @relation(fields: [bankAccountId], references: [id])\n  currency     Currency?      @relation(fields: [currencyId], references: [id])\n\n  @@index([tenantId])\n  @@index([journalEntryId])\n  @@index([accountId])\n  @@index([tenantId, cashboxId])\n  @@index([tenantId, bankAccountId])\n  @@index([tenantId, currencyId])\n  @@index([accountId, currencyId])\n  @@map(\"journal_lines\")\n}\n\n// ─── AI Agent ────────────────────────────────────────────────────────────────\n// Display history (ai_conversations / ai_messages) is separate from the agent's\n// working memory (ai_checkpoints / ai_checkpoint_writes, LangGraph checkpointer).\n\nenum AiMessageRole {\n  USER\n  ASSISTANT\n  SYSTEM\n}\n\nmodel AiConversation {\n  id            String   @id @default(uuid())\n  tenantId      String   @map(\"tenant_id\")\n  /// No FK — matches the previous ai-chat schema.\n  userId        String   @map(\"user_id\")\n  title         String?\n  lastMessageAt DateTime @default(now()) @map(\"last_message_at\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  tenant   Tenant      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  messages AiMessage[]\n\n  @@index([tenantId, userId, lastMessageAt])\n  @@map(\"ai_conversations\")\n}\n\nmodel AiMessage {\n  /// Client-generated for USER messages (AI SDK id), server-generated for ASSISTANT.\n  id             String        @id @default(uuid())\n  tenantId       String        @map(\"tenant_id\")\n  conversationId String        @map(\"conversation_id\")\n  role           AiMessageRole\n  /// AI SDK UIMessage.parts, stored verbatim.\n  parts          Json          @db.JsonB\n  /// { model, finishReason, error }\n  metadata       Json?         @db.JsonB\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n  updatedAt      DateTime      @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  conversation AiConversation @relation(fields: [conversationId], references: [id], onDelete: Cascade)\n\n  @@index([conversationId, createdAt])\n  @@map(\"ai_messages\")\n}\n\n/// LangGraph checkpoint. thread_id = AiConversation.id. Payload is LangGraph serde (type + bytes).\nmodel AiCheckpoint {\n  threadId           String   @map(\"thread_id\")\n  checkpointNs       String   @default(\"\") @map(\"checkpoint_ns\")\n  checkpointId       String   @map(\"checkpoint_id\")\n  parentCheckpointId String?  @map(\"parent_checkpoint_id\")\n  tenantId           String   @map(\"tenant_id\")\n  type               String\n  checkpoint         Bytes\n  metadata           Json     @db.JsonB\n  createdAt          DateTime @default(now()) @map(\"created_at\")\n\n  @@id([threadId, checkpointNs, checkpointId])\n  @@index([tenantId])\n  @@map(\"ai_checkpoints\")\n}\n\n/// LangGraph pending writes for a checkpoint.\nmodel AiCheckpointWrite {\n  threadId     String @map(\"thread_id\")\n  checkpointNs String @default(\"\") @map(\"checkpoint_ns\")\n  checkpointId String @map(\"checkpoint_id\")\n  taskId       String @map(\"task_id\")\n  idx          Int\n  channel      String\n  type         String\n  value        Bytes\n  tenantId     String @map(\"tenant_id\")\n\n  @@id([threadId, checkpointNs, checkpointId, taskId, idx])\n  @@index([tenantId])\n  @@map(\"ai_checkpoint_writes\")\n}\n\n// ─── Audit Log ────────────────────────────────────────────────────────────────\n/// ⚠ POLYMORPHIC RELATION — entityType + entityId identify the audited record.\n/// Prisma cannot enforce a foreign key on a polymorphic field.\n/// CASCADE DELETION must be handled at the APPLICATION LAYER (or via DB trigger):\n/// when any entity (Invoice, Payment, Expense, etc.) is hard-deleted, the\n/// corresponding AuditLog rows must be deleted in the same transaction.\nmodel AuditLog {\n  id            String   @id @default(uuid())\n  tenantId      String   @map(\"tenant_id\")\n  userId        String   @map(\"user_id\") // \"system\" for scheduler / non-user work\n  action        String // e.g. CREATE, UPDATE, DELETE, JOURNAL_POST, OPENING_SESSION_LOCK\n  entityType    String   @map(\"entity_type\") // e.g. \"payments\", \"journal_entry\"\n  entityId      String   @map(\"entity_id\")\n  oldValues     Json?    @map(\"old_values\")\n  newValues     Json?    @map(\"new_values\")\n  ipAddress     String?  @map(\"ip_address\")\n  /// HTTP | GL | SCHEDULER | BUSINESS_SETUP | SYSTEM | AI_AGENT — see RequestContext.AuditSource\n  source        String   @default(\"HTTP\")\n  /// Joins this row to its request's log lines and sibling audit rows.\n  correlationId String?  @map(\"correlation_id\")\n  /// Free-form context, e.g. { method, route, handler } or { taskType }.\n  metadata      Json?\n  /// Append-only: a DB trigger rejects UPDATE (migration audit_log_observability).\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId])\n  @@index([tenantId, entityType, entityId])\n  @@index([tenantId, createdAt])\n  @@index([correlationId])\n  @@map(\"audit_logs\")\n}\n\n// ─── Bank Account ────────────────────────────────────────────────────────────\n// Subledger dimension over the Bank control account (FinancialSetting.defaultBankAccountId).\n// No dedicated GL field — shared control account + bankAccountId on JournalLine (ADR-2).\nmodel BankAccount {\n  id            String   @id @default(uuid())\n  tenantId      String   @map(\"tenant_id\")\n  code          String\n  name          Json     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  currencyId    String   @map(\"currency_id\")\n  accountNumber String?  @map(\"account_number\")\n  bankName      String?  @map(\"bank_name\")\n  /// Optional branch reference — a company-level account is legitimate.\n  branchId      String?  @map(\"branch_id\")\n  balance       Decimal  @default(0) @db.Decimal(18, 4)\n  isActive      Boolean  @default(true) @map(\"is_active\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  tenant                     Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  currency                   Currency                    @relation(fields: [currencyId], references: [id])\n  branch                     Branch?                     @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  journalLines               JournalLine[]\n  openingBalanceSessionLines OpeningBalanceSessionLine[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@index([tenantId, currencyId])\n  @@index([tenantId, branchId])\n  @@map(\"bank_accounts\")\n}\n\n// ─── Branch ───────────────────────────────────────────────────────────────────\n/// Operational division of a Tenant (\"Business Location\" in the UI). Carries an\n/// operational identity only — no legal name or tax registration; the Tenant is\n/// the legal entity. See docs/adr/0005 and docs/adr/0007.\nmodel Branch {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  code      String\n  name      Json     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  address   String?\n  phone     String?\n  email     String?\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant            Tenant             @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  warehouses        BranchWarehouse[]\n  cashboxes         Cashbox[]\n  documentSequences DocumentSequence[]\n  invoices          Invoice[]\n  journalEntries    JournalEntry[]\n  payments          Payment[]\n  expenses          Expense[]\n  bankAccounts      BankAccount[]\n  posSettings       PosSetting[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"branches\")\n}\n\n// ─── Branch ⇄ Warehouse ───────────────────────────────────────────────────────\n/// Many-to-many: a warehouse must belong to at least one branch; a branch may\n/// have zero warehouses. Enforced at the API boundary, not by the schema.\nmodel BranchWarehouse {\n  id          String   @id @default(uuid())\n  tenantId    String   @map(\"tenant_id\")\n  branchId    String   @map(\"branch_id\")\n  warehouseId String   @map(\"warehouse_id\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n\n  tenant    Tenant    @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  branch    Branch    @relation(fields: [branchId], references: [id], onDelete: Cascade)\n  warehouse Warehouse @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n\n  @@unique([branchId, warehouseId])\n  @@index([tenantId])\n  @@index([warehouseId])\n  @@map(\"branch_warehouses\")\n}\n\n// ─── Brand ────────────────────────────────────────────────────────────────────\nmodel Brand {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  name      String\n  imageUrl  String?  @map(\"image_url\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  items  Item[]\n\n  @@unique([tenantId, name])\n  @@index([tenantId])\n  @@map(\"brands\")\n}\n\n// ─── Payment Type Enum ────────────────────────────────────────────────────────\nenum PaymentType {\n  RECEIPT\n  PAYMENT\n  ADJUSTMENT\n}\n\n// ─── Payment Status Enum ──────────────────────────────────────────────────────\nenum PaymentStatus {\n  DRAFT\n  POSTED\n  CANCELLED\n}\n\n// ─── Cashbox ──────────────────────────────────────────────────────────────────\nmodel Cashbox {\n  id         String   @id @default(uuid())\n  tenantId   String   @map(\"tenant_id\")\n  code       String\n  name       Json     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  currencyId String   @map(\"currency_id\")\n  /// Nullable in the database; required at the API boundary (Phase 1.1 backfill\n  /// safety). See docs/adr/0007.\n  branchId   String?  @map(\"branch_id\")\n  balance    Decimal  @default(0) @db.Decimal(18, 4)\n  isActive   Boolean  @default(true) @map(\"is_active\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  tenant                     Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  currency                   Currency                    @relation(fields: [currencyId], references: [id])\n  branch                     Branch?                     @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  expenses                   Expense[]\n  payments                   Payment[]\n  journalLines               JournalLine[]\n  openingBalanceSessionLines OpeningBalanceSessionLine[]\n  posSettings                PosSetting[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"cashboxes\")\n}\n\n// ─── Payment ──────────────────────────────────────────────────────────────────\nmodel Payment {\n  id                String        @id @default(uuid())\n  tenantId          String        @map(\"tenant_id\")\n  number            String\n  type              PaymentType\n  date              DateTime\n  cashboxId         String        @map(\"cashbox_id\")\n  partyId           String?       @map(\"party_id\")\n  /// Branch the payment is attributed to. Nullable in the DB for backfill\n  /// safety; required at the API boundary (Phase 1.1, #33).\n  branchId          String?       @map(\"branch_id\")\n  currencyId        String        @map(\"currency_id\")\n  /// Exchange rate of the payment currency to tenant base currency, locked at posting time.\n  exchangeRate      Decimal       @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  fiscalPeriodId    String        @map(\"fiscal_period_id\")\n  amount            Decimal       @db.Decimal(18, 4)\n  allocatedAmount   Decimal       @default(0) @map(\"allocated_amount\") @db.Decimal(18, 4)\n  unallocatedAmount Decimal       @default(0) @map(\"unallocated_amount\") @db.Decimal(18, 4)\n  status            PaymentStatus @default(DRAFT)\n  notes             String?\n  postedAt          DateTime?     @map(\"posted_at\")\n  postedBy          String?       @map(\"posted_by\")\n  cancelledAt       DateTime?     @map(\"cancelled_at\")\n  cancelledBy       String?       @map(\"cancelled_by\")\n  createdBy         String        @map(\"created_by\")\n  createdAt         DateTime      @default(now()) @map(\"created_at\")\n  updatedAt         DateTime      @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  cashbox      Cashbox             @relation(fields: [cashboxId], references: [id])\n  party        Party?              @relation(fields: [partyId], references: [id])\n  branch       Branch?             @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  currency     Currency            @relation(fields: [currencyId], references: [id])\n  fiscalPeriod FiscalPeriod        @relation(fields: [fiscalPeriodId], references: [id])\n  allocations  PaymentAllocation[]\n\n  @@unique([tenantId, number])\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, branchId])\n  @@map(\"payments\")\n}\n\n// ─── Payment Allocation ───────────────────────────────────────────────────────\nmodel PaymentAllocation {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  paymentId String   @map(\"payment_id\")\n  invoiceId String   @map(\"invoice_id\")\n  amount    Decimal  @db.Decimal(18, 4)\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  payment Payment @relation(fields: [paymentId], references: [id], onDelete: Cascade)\n  invoice Invoice @relation(fields: [invoiceId], references: [id])\n\n  @@index([tenantId])\n  @@index([paymentId])\n  @@map(\"payment_allocations\")\n}\n\n// ─── CatalogEntity ────────────────────────────────────────────────────────────\nmodel CatalogEntity {\n  id         String   @id @default(uuid())\n  tenantId   String   @map(\"tenant_id\")\n  name       String\n  kind       String\n  parentId   String?  @map(\"parent_id\")\n  attributes Json?\n  isActive   Boolean  @default(true) @map(\"is_active\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  tenant    Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  parent    CatalogEntity?      @relation(\"CatalogHierarchy\", fields: [parentId], references: [id])\n  children  CatalogEntity[]     @relation(\"CatalogHierarchy\")\n  itemLinks ItemCatalogEntity[]\n\n  @@index([tenantId])\n  @@index([tenantId, kind])\n  @@index([tenantId, parentId])\n  @@map(\"catalog_entities\")\n}\n\n// ─── Code Sequence ────────────────────────────────────────────────────────────\nmodel CodeSequence {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  entity    String // 'warehouse' | 'cashbox' | 'item' | 'bank_account'\n  nextValue Int      @default(1) @map(\"next_value\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, entity])\n  @@index([tenantId])\n  @@map(\"code_sequences\")\n}\n\n// ─── Currency ─────────────────────────────────────────────────────────────────\nmodel Currency {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  code      String // e.g. SYP, USD\n  name      Json     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  symbol    Json?    @db.JsonB // LocalizedString: { ar: string; en?: string }\n  isBase    Boolean  @default(false) @map(\"is_base\")\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant                     Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  cashboxes                  Cashbox[]\n  bankAccounts               BankAccount[]\n  journalLines               JournalLine[]\n  invoices                   Invoice[]\n  payments                   Payment[]\n  baseForTenants             Tenant[]                    @relation(\"TenantBaseCurrency\")\n  expenses                   Expense[]\n  openingBalanceSessionLines OpeningBalanceSessionLine[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"currencies\")\n}\n\nenum FieldType {\n  TEXT\n  DATE\n  NUMBER\n  SELECT\n  BOOLEAN\n  MULTI_SELECT\n  FILE\n}\n\nmodel CustomField {\n  id           String    @id @default(uuid())\n  tenantId     String    @map(\"tenant_id\")\n  module       String\n  name         Json      @db.JsonB // LocalizedString: { ar: string; en?: string }\n  label        Json      @db.JsonB // LocalizedString: { ar: string; en?: string }\n  type         FieldType\n  defaultValue String?   @map(\"default_value\")\n  placeholder  Json?     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  options      String[]\n  isRequired   Boolean   @default(false) @map(\"is_required\")\n  showInList   Boolean   @default(false) @map(\"show_in_list\")\n  createdAt    DateTime  @default(now()) @map(\"created_at\")\n\n  values CustomFieldValue[]\n\n  @@index([tenantId, module])\n  @@map(\"custom_fields\")\n}\n\n/// ⚠ POLYMORPHIC RELATION — entityType + entityId identify the owner record.\n/// Prisma cannot enforce a foreign key on a polymorphic field.\n/// CASCADE DELETION must be handled at the APPLICATION LAYER (or via DB trigger):\n/// when any entity (Item, Party, Invoice, etc.) is deleted, the matching\n/// CustomFieldValue rows must be deleted in the same transaction.\nmodel CustomFieldValue {\n  id         String @id @default(uuid())\n  tenantId   String @map(\"tenant_id\")\n  fieldId    String @map(\"field_id\")\n  entityType String @map(\"entity_type\")\n  entityId   String @map(\"entity_id\")\n  value      String\n\n  field CustomField @relation(fields: [fieldId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, fieldId, entityId])\n  @@index([tenantId, entityType, entityId])\n  @@index([fieldId, value])\n  @@map(\"custom_field_values\")\n}\n\n// ─── Document Sequence ────────────────────────────────────────────────────────\nmodel DocumentSequence {\n  id           String   @id @default(uuid())\n  tenantId     String   @map(\"tenant_id\")\n  documentType String   @map(\"document_type\") // e.g. \"PURCHASE_INVOICE\", \"SALES_INVOICE\", \"PAYMENT\"\n  prefix       String // e.g. \"PUR\", \"SAL\", \"PAY\"\n  nextNumber   Int      @default(1) @map(\"next_number\")\n  padding      Int      @default(5) // zero-pad length, e.g. 5 → 00001\n  /// Optional branch reference — the deliberate seam for future per-branch\n  /// numbering (docs/adr/0008). Numbering stays tenant-level in Phase 1.1.\n  branchId     String?  @map(\"branch_id\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  tenant                 Tenant   @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  branch                 Branch?  @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  defaultSalesForTenants Tenant[] @relation(\"TenantDefaultSalesSequence\")\n\n  @@unique([tenantId, documentType])\n  @@index([tenantId])\n  @@map(\"document_sequences\")\n}\n\n// ─── Expense Status Enum ──────────────────────────────────────────────────────\nenum ExpenseStatus {\n  DRAFT\n  POSTED\n  CANCELLED\n}\n\n// ─── Expense ──────────────────────────────────────────────────────────────────\nmodel Expense {\n  id             String        @id @default(uuid())\n  tenantId       String        @map(\"tenant_id\")\n  number         String\n  date           DateTime\n  cashboxId      String        @map(\"cashbox_id\")\n  /// Branch the expense is attributed to. Nullable in the DB for backfill\n  /// safety; required at the API boundary (Phase 1.1, #33).\n  branchId       String?       @map(\"branch_id\")\n  currencyId     String        @map(\"currency_id\")\n  /// Exchange rate of the expense currency to tenant base currency, locked at posting time.\n  exchangeRate   Decimal       @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  fiscalPeriodId String        @map(\"fiscal_period_id\")\n  totalAmount    Decimal       @default(0) @map(\"total_amount\") @db.Decimal(18, 4)\n  status         ExpenseStatus @default(DRAFT)\n  notes          String?\n  journalEntryId String?       @map(\"journal_entry_id\")\n  postedAt       DateTime?     @map(\"posted_at\")\n  postedBy       String?       @map(\"posted_by\")\n  cancelledAt    DateTime?     @map(\"cancelled_at\")\n  cancelledBy    String?       @map(\"cancelled_by\")\n  createdBy      String        @map(\"created_by\")\n  createdAt      DateTime      @default(now()) @map(\"created_at\")\n  updatedAt      DateTime      @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  cashbox      Cashbox       @relation(fields: [cashboxId], references: [id])\n  branch       Branch?       @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  currency     Currency      @relation(fields: [currencyId], references: [id])\n  fiscalPeriod FiscalPeriod  @relation(fields: [fiscalPeriodId], references: [id])\n  items        ExpenseItem[]\n\n  @@unique([tenantId, number])\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, branchId])\n  @@map(\"expenses\")\n}\n\n// ─── Expense Item ─────────────────────────────────────────────────────────────\nmodel ExpenseItem {\n  id          String  @id @default(uuid())\n  tenantId    String  @map(\"tenant_id\")\n  expenseId   String  @map(\"expense_id\")\n  accountId   String  @map(\"account_id\")\n  description String\n  amount      Decimal @db.Decimal(18, 4)\n  notes       String?\n  sortOrder   Int     @default(0) @map(\"sort_order\")\n\n  expense Expense        @relation(fields: [expenseId], references: [id], onDelete: Cascade)\n  account ChartOfAccount @relation(\"ExpenseItemAccount\", fields: [accountId], references: [id])\n\n  @@index([tenantId])\n  @@index([expenseId])\n  @@map(\"expense_items\")\n}\n\nmodel File {\n  id           String   @id @default(uuid())\n  tenantId     String\n  originalName String\n  mimeType     String\n  size         Int\n  extension    String?\n  folder       String\n  path         String   @unique\n  url          String\n  checksum     String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([tenantId])\n  @@map(\"files\")\n}\n\n// ─── Financial Setting ────────────────────────────────────────────────────────\n// Maps system-level accounting events to their default GL accounts per tenant.\n// One row per tenant (1-to-1 with Tenant). All account fields are optional —\n// they must be configured before posting transactions that need them.\nmodel FinancialSetting {\n  id                                  String   @id @default(uuid())\n  tenantId                            String   @unique @map(\"tenant_id\")\n  defaultSalesAccountId               String?  @map(\"default_sales_account_id\")\n  defaultPurchaseAccountId            String?  @map(\"default_purchase_account_id\")\n  defaultTaxAccountId                 String?  @map(\"default_tax_account_id\")\n  defaultReceivableAccountId          String?  @map(\"default_receivable_account_id\")\n  defaultPayableAccountId             String?  @map(\"default_payable_account_id\")\n  defaultInventoryAccountId           String?  @map(\"default_inventory_account_id\")\n  defaultCogsAccountId                String?  @map(\"default_cogs_account_id\")\n  defaultInventoryAdjustmentAccountId String?  @map(\"default_inventory_adjustment_account_id\")\n  defaultOpeningEquityAccountId       String?  @map(\"default_opening_equity_account_id\")\n  defaultCashAccountId                String?  @map(\"default_cash_account_id\")\n  defaultBankAccountId                String?  @map(\"default_bank_account_id\")\n  createdAt                           DateTime @default(now()) @map(\"created_at\")\n  updatedAt                           DateTime @updatedAt @map(\"updated_at\")\n\n  tenant                            Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  defaultSalesAccount               ChartOfAccount? @relation(\"DefaultSalesAccount\", fields: [defaultSalesAccountId], references: [id])\n  defaultPurchaseAccount            ChartOfAccount? @relation(\"DefaultPurchaseAccount\", fields: [defaultPurchaseAccountId], references: [id])\n  defaultTaxAccount                 ChartOfAccount? @relation(\"DefaultTaxAccount\", fields: [defaultTaxAccountId], references: [id])\n  defaultReceivableAccount          ChartOfAccount? @relation(\"DefaultReceivableAccount\", fields: [defaultReceivableAccountId], references: [id])\n  defaultPayableAccount             ChartOfAccount? @relation(\"DefaultPayableAccount\", fields: [defaultPayableAccountId], references: [id])\n  defaultInventoryAccount           ChartOfAccount? @relation(\"DefaultInventoryAccount\", fields: [defaultInventoryAccountId], references: [id])\n  defaultCogsAccount                ChartOfAccount? @relation(\"DefaultCogsAccount\", fields: [defaultCogsAccountId], references: [id])\n  defaultInventoryAdjustmentAccount ChartOfAccount? @relation(\"DefaultInventoryAdjustmentAccount\", fields: [defaultInventoryAdjustmentAccountId], references: [id])\n  defaultOpeningEquityAccount       ChartOfAccount? @relation(\"DefaultOpeningEquityAccount\", fields: [defaultOpeningEquityAccountId], references: [id])\n  defaultCashAccount                ChartOfAccount? @relation(\"DefaultCashAccount\", fields: [defaultCashAccountId], references: [id])\n  defaultBankAccount                ChartOfAccount? @relation(\"DefaultBankAccount\", fields: [defaultBankAccountId], references: [id])\n\n  @@index([tenantId])\n  @@map(\"financial_settings\")\n}\n\n// ─── Fiscal Period ────────────────────────────────────────────────────────────\nmodel FiscalPeriod {\n  id        String             @id @default(uuid())\n  tenantId  String             @map(\"tenant_id\")\n  name      String // e.g. \"2026\", \"Q1 2026\"\n  startDate DateTime           @map(\"start_date\")\n  endDate   DateTime           @map(\"end_date\")\n  status    FiscalPeriodStatus @default(OPEN)\n  createdAt DateTime           @default(now()) @map(\"created_at\")\n  updatedAt DateTime           @updatedAt @map(\"updated_at\")\n\n  tenant                 Tenant                  @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  stockMovements         StockMovement[]\n  invoices               Invoice[]\n  payments               Payment[]\n  journalEntries         JournalEntry[]\n  stockCounts            StockCount[]\n  expenses               Expense[]\n  openingBalanceSessions OpeningBalanceSession[]\n\n  @@index([tenantId])\n  @@map(\"fiscal_periods\")\n}\n\nenum FiscalPeriodStatus {\n  OPEN\n  CLOSED\n  LOCKED\n}\n\n// ─── Invoice Direction Enum ───────────────────────────────────────────────────\nenum InvoiceDirection {\n  PURCHASE\n  SALE\n}\n\n// ─── Invoice Status Enum ──────────────────────────────────────────────────────\nenum InvoiceStatus {\n  DRAFT\n  POSTED\n  CANCELLED\n}\n\n// ─── Invoice Type ─────────────────────────────────────────────────────────────\nmodel InvoiceType {\n  id           String           @id @default(uuid())\n  tenantId     String           @map(\"tenant_id\")\n  code         String\n  name         Json             @db.JsonB // LocalizedString: { ar: string; en?: string }\n  direction    InvoiceDirection\n  affectsStock Boolean          @default(true) @map(\"affects_stock\")\n  isActive     Boolean          @default(true) @map(\"is_active\")\n  createdAt    DateTime         @default(now()) @map(\"created_at\")\n  updatedAt    DateTime         @updatedAt @map(\"updated_at\")\n\n  tenant      Tenant       @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  invoices    Invoice[]\n  posSettings PosSetting[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"invoice_types\")\n}\n\n// ─── Invoice ──────────────────────────────────────────────────────────────────\nmodel Invoice {\n  id              String        @id @default(uuid())\n  tenantId        String        @map(\"tenant_id\")\n  invoiceTypeId   String        @map(\"invoice_type_id\")\n  number          String\n  date            DateTime\n  dueDate         DateTime?     @map(\"due_date\")\n  partyId         String        @map(\"party_id\")\n  warehouseId     String?       @map(\"warehouse_id\")\n  /// Branch the invoice is attributed to. Nullable in the DB for backfill\n  /// safety; required at the API boundary (Phase 1.1, #32).\n  branchId        String?       @map(\"branch_id\")\n  fiscalPeriodId  String        @map(\"fiscal_period_id\")\n  currencyId      String        @map(\"currency_id\")\n  /// Exchange rate of the invoice currency to tenant base currency, locked at posting time.\n  exchangeRate    Decimal       @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  status          InvoiceStatus @default(DRAFT)\n  subtotal        Decimal       @default(0) @db.Decimal(18, 4)\n  discountAmount  Decimal       @default(0) @map(\"discount_amount\") @db.Decimal(18, 4)\n  taxAmount       Decimal       @default(0) @map(\"tax_amount\") @db.Decimal(18, 4)\n  total           Decimal       @default(0) @db.Decimal(18, 4)\n  notes           String?\n  /**\n   * Idempotency key for POS checkout retries; null for non-POS invoices.\n   */\n  clientRequestId String?       @map(\"client_request_id\")\n  postedAt        DateTime?     @map(\"posted_at\")\n  postedBy        String?       @map(\"posted_by\")\n  cancelledAt     DateTime?     @map(\"cancelled_at\")\n  cancelledBy     String?       @map(\"cancelled_by\")\n  createdBy       String        @map(\"created_by\")\n  createdAt       DateTime      @default(now()) @map(\"created_at\")\n  updatedAt       DateTime      @updatedAt @map(\"updated_at\")\n\n  tenant             Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  invoiceType        InvoiceType         @relation(fields: [invoiceTypeId], references: [id])\n  party              Party               @relation(fields: [partyId], references: [id])\n  warehouse          Warehouse?          @relation(fields: [warehouseId], references: [id])\n  branch             Branch?             @relation(fields: [branchId], references: [id], onDelete: Restrict)\n  fiscalPeriod       FiscalPeriod        @relation(fields: [fiscalPeriodId], references: [id])\n  currency           Currency            @relation(fields: [currencyId], references: [id])\n  lines              InvoiceLine[]\n  paymentAllocations PaymentAllocation[]\n\n  @@unique([tenantId, number])\n  @@unique([tenantId, clientRequestId])\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@index([tenantId, branchId])\n  @@map(\"invoices\")\n}\n\n// ─── Invoice Line ─────────────────────────────────────────────────────────────\nmodel InvoiceLine {\n  id              String  @id @default(uuid())\n  tenantId        String  @map(\"tenant_id\")\n  invoiceId       String  @map(\"invoice_id\")\n  itemId          String  @map(\"item_id\")\n  unitId          String  @map(\"unit_id\")\n  quantity        Decimal @db.Decimal(18, 4)\n  unitPrice       Decimal @map(\"unit_price\") @db.Decimal(18, 4)\n  discountPercent Decimal @default(0) @map(\"discount_percent\") @db.Decimal(5, 2)\n  discountAmount  Decimal @default(0) @map(\"discount_amount\") @db.Decimal(18, 4)\n  taxPercent      Decimal @default(0) @map(\"tax_percent\") @db.Decimal(5, 2)\n  taxAmount       Decimal @default(0) @map(\"tax_amount\") @db.Decimal(18, 4)\n  total           Decimal @db.Decimal(18, 4)\n  notes           String?\n  sortOrder       Int     @default(0) @map(\"sort_order\")\n\n  invoice Invoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  item    Item    @relation(fields: [itemId], references: [id])\n  unit    Unit    @relation(fields: [unitId], references: [id])\n\n  @@index([tenantId])\n  @@index([invoiceId])\n  @@map(\"invoice_lines\")\n}\n\n// ─── ItemCatalogEntity ────────────────────────────────────────────────────────\nmodel ItemCatalogEntity {\n  id              String   @id @default(uuid())\n  tenantId        String   @map(\"tenant_id\")\n  itemId          String   @map(\"item_id\")\n  catalogEntityId String   @map(\"catalog_entity_id\")\n  createdAt       DateTime @default(now()) @map(\"created_at\")\n\n  tenant        Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  item          Item          @relation(fields: [itemId], references: [id], onDelete: Cascade)\n  catalogEntity CatalogEntity @relation(fields: [catalogEntityId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, itemId, catalogEntityId])\n  @@index([tenantId, itemId])\n  @@index([tenantId, catalogEntityId])\n  @@map(\"item_catalog_entities\")\n}\n\n// ─── Item Category ───────────────────────────────────────────────────────────\nmodel ItemCategory {\n  id          String   @id @default(uuid())\n  tenantId    String   @map(\"tenant_id\")\n  name        String\n  description String?\n  imageUrl    String?  @map(\"image_url\")\n  parentId    String?  @map(\"parent_id\")\n  isActive    Boolean  @default(true) @map(\"is_active\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  tenant   Tenant         @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  parent   ItemCategory?  @relation(\"CategoryHierarchy\", fields: [parentId], references: [id])\n  children ItemCategory[] @relation(\"CategoryHierarchy\")\n  items    Item[]\n\n  @@unique([tenantId, name])\n  @@index([tenantId])\n  @@map(\"item_categories\")\n}\n\nenum RelationType {\n  compatible_with\n  replaces\n  requires\n}\n\n// ─── ItemRelation ─────────────────────────────────────────────────────────────\nmodel ItemRelation {\n  id            String       @id @default(uuid())\n  tenantId      String       @map(\"tenant_id\")\n  itemId        String       @map(\"item_id\")\n  relatedItemId String       @map(\"related_item_id\")\n  relationType  RelationType @map(\"relation_type\")\n  notes         String?\n  createdAt     DateTime     @default(now()) @map(\"created_at\")\n  updatedAt     DateTime     @updatedAt @map(\"updated_at\")\n\n  tenant      Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  item        Item   @relation(\"ItemRelations\", fields: [itemId], references: [id], onDelete: Cascade)\n  relatedItem Item   @relation(\"ItemRelatedTo\", fields: [relatedItemId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, itemId, relatedItemId, relationType])\n  @@index([tenantId, itemId])\n  @@index([tenantId, relatedItemId])\n  @@map(\"item_relations\")\n}\n\nenum ItemType {\n  product\n  service\n}\n\n// ─── Item ─────────────────────────────────────────────────────────────────────\nmodel Item {\n  id                  String   @id @default(uuid())\n  tenantId            String   @map(\"tenant_id\")\n  code                String\n  name                String\n  barcode             String?\n  categoryId          String   @map(\"category_id\")\n  baseUnitId          String   @map(\"base_unit_id\")\n  brandId             String?  @map(\"brand_id\")\n  defaultSellingPrice Decimal? @map(\"default_selling_price\") @db.Decimal(18, 4)\n  latestPurchasePrice Decimal? @map(\"latest_purchase_price\") @db.Decimal(18, 4)\n  mainImageUrl        String?  @map(\"main_image_url\")\n\n  description String?\n  note        String?\n\n  galleryUrls String[] @map(\"gallery_urls\")\n  itemType    ItemType @default(product) @map(\"item_type\")\n  isActive    Boolean  @default(true) @map(\"is_active\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  tenant              Tenant              @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  category            ItemCategory        @relation(fields: [categoryId], references: [id])\n  baseUnit            Unit                @relation(fields: [baseUnitId], references: [id])\n  brand               Brand?              @relation(fields: [brandId], references: [id])\n  warehouseItems      WarehouseItem[]\n  stockBalances       StockBalance[]\n  stockMovements      StockMovement[]\n  invoiceLines        InvoiceLine[]\n  stockCountLines     StockCountLine[]\n  itemRelations       ItemRelation[]      @relation(\"ItemRelations\")\n  itemRelatedTo       ItemRelation[]      @relation(\"ItemRelatedTo\")\n  itemCatalogEntities ItemCatalogEntity[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@index([tenantId, itemType])\n  @@index([tenantId, brandId])\n  @@map(\"items\")\n}\n\n// ─── Opening Balance Session ──────────────────────────────────────────────────\n// ADR-3 / ADR-4 / ADR-5 — unified draft → validate → review → post → lock lifecycle.\n// Operational dimensions (partyId / cashboxId / bankAccountId / currencyId) live on\n// session lines; the GL control accounts are resolved at post time by\n// OpeningSessionPostedPolicy from FinancialSettings + party overrides — never stored here.\nenum OpeningBalanceSessionStatus {\n  DRAFT\n  VALIDATED\n  REVIEWED\n  POSTED\n  LOCKED\n}\n\nenum OpeningBalanceDimension {\n  CASHBOX\n  BANK_ACCOUNT\n  PARTY\n  ACCOUNT\n}\n\nenum OpeningBalancePartySide {\n  AR\n  AP\n}\n\nmodel OpeningBalanceSession {\n  id             String                      @id @default(uuid())\n  tenantId       String                      @map(\"tenant_id\")\n  number         String\n  fiscalPeriodId String                      @map(\"fiscal_period_id\")\n  status         OpeningBalanceSessionStatus @default(DRAFT)\n  description    String?\n  postedAt       DateTime?                   @map(\"posted_at\")\n  postedBy       String?                     @map(\"posted_by\")\n  lockedAt       DateTime?                   @map(\"locked_at\")\n  lockedBy       String?                     @map(\"locked_by\")\n  createdBy      String                      @map(\"created_by\")\n  createdAt      DateTime                    @default(now()) @map(\"created_at\")\n  updatedAt      DateTime                    @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  fiscalPeriod FiscalPeriod                @relation(fields: [fiscalPeriodId], references: [id])\n  lines        OpeningBalanceSessionLine[]\n\n  @@unique([tenantId, number])\n  @@index([tenantId])\n  @@index([tenantId, status])\n  @@map(\"opening_balance_sessions\")\n}\n\nmodel OpeningBalanceSessionLine {\n  id            String                   @id @default(uuid())\n  tenantId      String                   @map(\"tenant_id\")\n  sessionId     String                   @map(\"session_id\")\n  dimension     OpeningBalanceDimension\n  accountId     String?                  @map(\"account_id\")\n  partyId       String?                  @map(\"party_id\")\n  cashboxId     String?                  @map(\"cashbox_id\")\n  bankAccountId String?                  @map(\"bank_account_id\")\n  currencyId    String?                  @map(\"currency_id\")\n  /// AR = debit the receivable control account (money owed to us); AP = credit the payable control account (money we owe).\n  partySide     OpeningBalancePartySide? @map(\"party_side\")\n  /// Signed transaction-currency amount: positive increases the target balance (asset → debit, liability/equity → credit).\n  amount        Decimal                  @db.Decimal(18, 4)\n  /// Locked exchange rate to tenant base currency (ADR-5).\n  exchangeRate  Decimal                  @default(1) @map(\"exchange_rate\") @db.Decimal(18, 6)\n  createdAt     DateTime                 @default(now()) @map(\"created_at\")\n  updatedAt     DateTime                 @updatedAt @map(\"updated_at\")\n\n  session     OpeningBalanceSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n  tenant      Tenant                @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  party       Party?                @relation(fields: [partyId], references: [id])\n  cashbox     Cashbox?              @relation(fields: [cashboxId], references: [id])\n  bankAccount BankAccount?          @relation(fields: [bankAccountId], references: [id])\n  account     ChartOfAccount?       @relation(fields: [accountId], references: [id])\n  currency    Currency?             @relation(fields: [currencyId], references: [id])\n\n  @@index([tenantId, sessionId])\n  @@map(\"opening_balance_session_lines\")\n}\n\n// ─── Outbox ───────────────────────────────────────────────────────────────────\n/// Phase 8.4 — durable event repository for the optional async seam.\n/// Dual-write mode: AccountingPostingFacade writes the outbox row in the same\n/// transaction as the journal entry. OFF by default (OUTBOX_ENABLED=false);\n/// the synchronous posting path remains the production behavior (8.4.4).\nenum OutboxStatus {\n  PENDING\n  PROCESSING\n  DELIVERED\n  DEAD\n}\n\nmodel OutboxEvent {\n  id          String       @id @default(uuid())\n  tenantId    String       @map(\"tenant_id\")\n  /// Stable routing key, e.g. 'accounting.journal-posted'.\n  topic       String\n  payload     Json         @db.JsonB\n  status      OutboxStatus @default(PENDING)\n  attempts    Int          @default(0)\n  maxAttempts Int          @default(5) @map(\"max_attempts\")\n  lastError   String?      @map(\"last_error\")\n  /// Earliest time the next attempt may run (retry backoff).\n  availableAt DateTime     @default(now()) @map(\"available_at\")\n  /// Set while status = PROCESSING; stale locks are reclaimable by the worker.\n  lockedAt    DateTime?    @map(\"locked_at\")\n  deliveredAt DateTime?    @map(\"delivered_at\")\n  createdAt   DateTime     @default(now()) @map(\"created_at\")\n  updatedAt   DateTime     @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([status, availableAt])\n  @@index([tenantId, createdAt])\n  @@map(\"outbox_events\")\n}\n\n// ─── Party ─────────────────────────────────────────────────────────────────────\nenum PartyType {\n  CUSTOMER\n  SUPPLIER\n  CUSTOMER_SUPPLIER\n}\n\nmodel Party {\n  id                  String    @id @default(uuid())\n  tenantId            String    @map(\"tenant_id\")\n  code                String?\n  name                String\n  type                PartyType\n  phone               String?\n  email               String?\n  address             String?\n  isActive            Boolean   @default(true) @map(\"is_active\")\n  receivableAccountId String?   @map(\"receivable_account_id\")\n  payableAccountId    String?   @map(\"payable_account_id\")\n  createdAt           DateTime  @default(now()) @map(\"created_at\")\n  updatedAt           DateTime  @updatedAt @map(\"updated_at\")\n\n  tenant                     Tenant                      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  invoices                   Invoice[]\n  payments                   Payment[]\n  journalLines               JournalLine[]               @relation(\"JournalLineParty\")\n  openingBalanceSessionLines OpeningBalanceSessionLine[]\n  receivableAccount          ChartOfAccount?             @relation(\"PartyReceivableAccount\", fields: [receivableAccountId], references: [id])\n  payableAccount             ChartOfAccount?             @relation(\"PartyPayableAccount\", fields: [payableAccountId], references: [id])\n  posSettings                PosSetting[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@index([tenantId, type])\n  @@map(\"parties\")\n}\n\n// ─── Permission (global catalog — no tenant scope) ───────────────────────────\nmodel Permission {\n  id        String   @id @default(uuid())\n  key       String   @unique // \"resource.action\", e.g. \"invoices.post\"\n  resource  String\n  action    String\n  group     String\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  rolePermissions RolePermission[]\n\n  @@index([resource])\n  @@index([group])\n  @@map(\"permissions\")\n}\n\n// ─── Role ⇄ Permission ───────────────────────────────────────────────────────\nmodel RolePermission {\n  id           String   @id @default(uuid())\n  roleId       String   @map(\"role_id\")\n  permissionId String   @map(\"permission_id\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n\n  role       Role       @relation(fields: [roleId], references: [id], onDelete: Cascade)\n  permission Permission @relation(fields: [permissionId], references: [id], onDelete: Cascade)\n\n  @@unique([roleId, permissionId])\n  @@index([roleId])\n  @@map(\"role_permissions\")\n}\n\n// ─── POS Setting ──────────────────────────────────────────────────────────────\n// One row per tenant. Configures the walk-in customer, POS invoice type, till\n// cashbox, and issuing warehouse used by POS checkout (apps/api modules/pos).\nmodel PosSetting {\n  id             String   @id @default(uuid())\n  tenantId       String   @unique @map(\"tenant_id\")\n  defaultPartyId String   @map(\"default_party_id\")\n  invoiceTypeId  String   @map(\"invoice_type_id\")\n  cashboxId      String   @map(\"cashbox_id\")\n  warehouseId    String   @map(\"warehouse_id\")\n  /// Branch the terminal sells on behalf of. Nullable in the database for\n  /// backfill safety; required at the API boundary (Phase 1.1, #34).\n  branchId       String?  @map(\"branch_id\")\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant      @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  defaultParty Party       @relation(fields: [defaultPartyId], references: [id], onDelete: Restrict)\n  invoiceType  InvoiceType @relation(fields: [invoiceTypeId], references: [id], onDelete: Restrict)\n  cashbox      Cashbox     @relation(fields: [cashboxId], references: [id], onDelete: Restrict)\n  warehouse    Warehouse   @relation(fields: [warehouseId], references: [id], onDelete: Restrict)\n  branch       Branch?     @relation(fields: [branchId], references: [id], onDelete: Restrict)\n\n  @@index([tenantId, branchId])\n  @@map(\"pos_settings\")\n}\n\n// ─── Reconciliation Run ───────────────────────────────────────────────────────\n/// Phase 7.5 — history of reconciliation runs. Each run stores its finding\n/// fingerprints so the next run can detect NEW or GROWN drift (drift-baselines.md).\n/// Append-only by convention: written once by ReconciliationMonitorService.\nmodel ReconciliationRun {\n  id            String   @id @default(uuid())\n  tenantId      String   @map(\"tenant_id\")\n  /// SCHEDULED | MANUAL | BUSINESS_SETUP\n  trigger       String\n  passed        Boolean\n  findingCount  Int      @map(\"finding_count\")\n  /// Record<fingerprint, |difference|> — see reconciliation-checks.ts\n  findings      Json\n  /// string[] — fingerprints new or grown vs the previous run\n  newFindings   Json     @map(\"new_findings\")\n  /// Full ReconciliationResultDto at run time\n  report        Json\n  correlationId String?  @map(\"correlation_id\")\n  createdAt     DateTime @default(now()) @map(\"created_at\")\n  updatedAt     DateTime @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@index([tenantId, createdAt])\n  @@map(\"reconciliation_runs\")\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../../generated/client\"\n}\n\nenum SetupTaskType {\n  CURRENCIES\n  FISCAL_PERIOD\n  CHART_OF_ACCOUNTS\n  FINANCIAL_MAPPINGS\n  DOCUMENT_SEQUENCES\n  CASHBOXES\n  BANK_ACCOUNTS\n  WAREHOUSES\n  PRODUCTS\n  CUSTOMERS\n  SUPPLIERS\n  OPENING_CASH_BALANCES\n  OPENING_BANK_BALANCES\n  OPENING_RECEIVABLES\n  OPENING_PAYABLES\n  OPENING_INVENTORY\n  RECONCILIATION\n}\n\nenum SetupTaskStatus {\n  BLOCKED\n  READY\n  COMPLETED\n  SKIPPED\n}\n\n// ─── SetupTask ──────────────────────────────────────────────────────────────\n// One row per (tenant, task type). Drives the Business Setup dependency engine.\nmodel SetupTask {\n  id           String          @id @default(uuid())\n  tenantId     String          @map(\"tenant_id\")\n  tenant       Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  type         SetupTaskType\n  status       SetupTaskStatus @default(BLOCKED)\n  required     Boolean         @default(true)\n  dependencies SetupTaskType[]\n  progress     Json?           @db.JsonB\n  metadata     Json?           @db.JsonB\n  completedAt  DateTime?       @map(\"completed_at\")\n  createdAt    DateTime        @default(now()) @map(\"created_at\")\n  updatedAt    DateTime        @updatedAt @map(\"updated_at\")\n\n  @@unique([tenantId, type])\n  @@index([tenantId, status])\n  @@map(\"setup_tasks\")\n}\n\n// ─── Stock Count Status Enum ──────────────────────────────────────────────────\nenum StockCountStatus {\n  DRAFT\n  POSTED\n  CANCELLED\n}\n\n// ─── Stock Count ──────────────────────────────────────────────────────────────\nmodel StockCount {\n  id       String @id @default(uuid())\n  tenantId String @map(\"tenant_id\")\n  number   String\n\n  date           DateTime\n  warehouseId    String           @map(\"warehouse_id\")\n  fiscalPeriodId String           @map(\"fiscal_period_id\")\n  status         StockCountStatus @default(DRAFT)\n  notes          String?\n  postedAt       DateTime?        @map(\"posted_at\")\n  postedBy       String?          @map(\"posted_by\")\n  createdBy      String           @map(\"created_by\")\n  createdAt      DateTime         @default(now()) @map(\"created_at\")\n  updatedAt      DateTime         @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant           @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  warehouse    Warehouse        @relation(fields: [warehouseId], references: [id])\n  fiscalPeriod FiscalPeriod     @relation(fields: [fiscalPeriodId], references: [id])\n  lines        StockCountLine[]\n\n  @@unique([tenantId, number])\n  @@index([tenantId])\n  @@map(\"stock_counts\")\n}\n\n// ─── Stock Count Line ─────────────────────────────────────────────────────────\nmodel StockCountLine {\n  id              String  @id @default(uuid())\n  tenantId        String  @map(\"tenant_id\")\n  stockCountId    String  @map(\"stock_count_id\")\n  itemId          String  @map(\"item_id\")\n  systemQuantity  Decimal @map(\"system_quantity\") @db.Decimal(18, 4)\n  countedQuantity Decimal @map(\"counted_quantity\") @db.Decimal(18, 4)\n  difference      Decimal @db.Decimal(18, 4)\n  notes           String?\n\n  stockCount StockCount @relation(fields: [stockCountId], references: [id], onDelete: Cascade)\n  item       Item       @relation(fields: [itemId], references: [id])\n\n  @@index([tenantId])\n  @@index([stockCountId])\n  @@map(\"stock_count_lines\")\n}\n\n// ─── Stock Movement Type ──────────────────────────────────────────────────────\nenum StockMovementType {\n  OPENING\n  PURCHASE\n  SALE\n  ADJUSTMENT\n  STOCK_COUNT\n  TRANSFER_IN\n  TRANSFER_OUT\n}\n\n// ─── Stock Balance (projection table for fast reads) ─────────────────────────\nmodel StockBalance {\n  id          String   @id @default(uuid())\n  tenantId    String   @map(\"tenant_id\")\n  warehouseId String   @map(\"warehouse_id\")\n  itemId      String   @map(\"item_id\")\n  quantity    Decimal  @default(0) @db.Decimal(18, 4)\n  averageCost Decimal  @default(0) @map(\"average_cost\") @db.Decimal(18, 4)\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  warehouse Warehouse @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n  item      Item      @relation(fields: [itemId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, warehouseId, itemId])\n  @@index([tenantId])\n  @@map(\"stock_balances\")\n}\n\n// ─── Stock Movement (source of truth ledger) ─────────────────────────────────\nmodel StockMovement {\n  id             String            @id @default(uuid())\n  tenantId       String            @map(\"tenant_id\")\n  warehouseId    String            @map(\"warehouse_id\")\n  itemId         String            @map(\"item_id\")\n  fiscalPeriodId String            @map(\"fiscal_period_id\")\n  movementType   StockMovementType @map(\"movement_type\")\n  quantity       Decimal           @db.Decimal(18, 4)\n  unitCost       Decimal           @default(0) @map(\"unit_cost\") @db.Decimal(18, 4)\n  referenceType  String?           @map(\"reference_type\") // e.g. \"invoice\", \"stock_count\"\n  referenceId    String?           @map(\"reference_id\")\n  notes          String?\n  createdAt      DateTime          @default(now()) @map(\"created_at\")\n  createdBy      String            @map(\"created_by\")\n\n  warehouse    Warehouse    @relation(fields: [warehouseId], references: [id])\n  item         Item         @relation(fields: [itemId], references: [id])\n  fiscalPeriod FiscalPeriod @relation(fields: [fiscalPeriodId], references: [id])\n\n  @@index([tenantId])\n  @@index([tenantId, itemId])\n  @@index([tenantId, warehouseId])\n  @@map(\"stock_movements\")\n}\n\n// ─── TagAssignment ────────────────────────────────────────────────────────────\n/// ⚠ POLYMORPHIC RELATION — entityType + entityId identify the tagged record.\n/// Prisma cannot enforce a foreign key on a polymorphic field.\n/// CASCADE DELETION must be handled at the APPLICATION LAYER (or via DB trigger):\n/// when any entity (Item, Party, Invoice, Warehouse, etc.) is deleted, the\n/// corresponding TagAssignment rows must be deleted in the same transaction.\nmodel TagAssignment {\n  id         String   @id @default(uuid())\n  tenantId   String   @map(\"tenant_id\")\n  tagId      String   @map(\"tag_id\")\n  entityType String   @map(\"entity_type\") // \"item\" | \"party\" | \"invoice\" | \"warehouse\"\n  entityId   String   @map(\"entity_id\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n\n  tag Tag @relation(fields: [tagId], references: [id], onDelete: Cascade)\n\n  @@unique([tagId, entityType, entityId])\n  @@index([tenantId, entityType, entityId])\n  @@map(\"tag_assignments\")\n}\n\n// ─── Tag ──────────────────────────────────────────────────────────────────────\nmodel Tag {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  name      String\n  color     String?\n  module    String // \"items\" | \"parties\" | \"invoices\" | \"warehouses\"\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant      Tenant          @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  assignments TagAssignment[]\n\n  @@unique([tenantId, name, module])\n  @@index([tenantId, module])\n  @@map(\"tags\")\n}\n\n// ─── Tenant Setting ───────────────────────────────────────────────────────────\nmodel TenantSetting {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  category  String // 'localization' | 'financial' | 'documents' | 'defaults'\n  key       String // registry key, e.g. 'timezone'\n  value     Json     @db.JsonB\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant Tenant @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n\n  @@unique([tenantId, key])\n  @@index([tenantId, category])\n  @@map(\"tenant_settings\")\n}\n\n// ─── Tenant ───────────────────────────────────────────────────────────────────\nmodel Tenant {\n  id        String  @id @default(uuid())\n  name      String\n  slug      String  @unique\n  address   String?\n  phone     String?\n  email     String?\n  logo      String?\n  legalName String? @map(\"legal_name\")\n  taxNumber String? @map(\"tax_number\")\n  website   String?\n\n  baseCurrencyId         String? @map(\"base_currency_id\")\n  defaultSalesSequenceId String? @map(\"default_sales_sequence_id\")\n\n  isActive                 Boolean   @default(true) @map(\"is_active\")\n  onboardingStep           Int       @default(0) @map(\"onboarding_step\")\n  onboardingCompletedAt    DateTime? @map(\"onboarding_completed_at\")\n  businessSetupProfile     Json?     @map(\"business_setup_profile\") @db.JsonB\n  businessSetupCompletedAt DateTime? @map(\"business_setup_completed_at\")\n  operationalReadiness     Json?     @map(\"operational_readiness\") @db.JsonB\n  createdAt                DateTime  @default(now()) @map(\"created_at\")\n  updatedAt                DateTime  @updatedAt @map(\"updated_at\")\n\n  users                      AppUser[]\n  roles                      Role[]\n  currencies                 Currency[]\n  fiscalPeriods              FiscalPeriod[]\n  documentSequences          DocumentSequence[]\n  codeSequences              CodeSequence[]\n  itemCategories             ItemCategory[]\n  units                      Unit[]\n  items                      Item[]\n  parties                    Party[]\n  branches                   Branch[]\n  branchWarehouses           BranchWarehouse[]\n  warehouses                 Warehouse[]\n  cashboxes                  Cashbox[]\n  bankAccounts               BankAccount[]\n  invoiceTypes               InvoiceType[]\n  invoices                   Invoice[]\n  payments                   Payment[]\n  chartOfAccounts            ChartOfAccount[]\n  journalEntries             JournalEntry[]\n  stockCounts                StockCount[]\n  auditLogs                  AuditLog[]\n  reconciliationRuns         ReconciliationRun[]\n  outboxEvents               OutboxEvent[]\n  aiConversations            AiConversation[]\n  aiMessages                 AiMessage[]\n  baseCurrency               Currency?                   @relation(\"TenantBaseCurrency\", fields: [baseCurrencyId], references: [id])\n  defaultSalesSequence       DocumentSequence?           @relation(\"TenantDefaultSalesSequence\", fields: [defaultSalesSequenceId], references: [id])\n  settings                   TenantSetting[]\n  financialSetting           FinancialSetting?\n  expenses                   Expense[]\n  tags                       Tag[]\n  itemRelations              ItemRelation[]\n  catalogEntities            CatalogEntity[]\n  itemCatalogEntities        ItemCatalogEntity[]\n  brands                     Brand[]\n  openingBalanceSessions     OpeningBalanceSession[]\n  openingBalanceSessionLines OpeningBalanceSessionLine[]\n  setupTasks                 SetupTask[]\n  posSetting                 PosSetting?\n\n  @@map(\"tenants\")\n}\n\n// ─── Unit ─────────────────────────────────────────────────────────────────────\nmodel Unit {\n  id           String   @id @default(uuid())\n  tenantId     String   @map(\"tenant_id\")\n  name         Json     @db.JsonB\n  abbreviation String\n  isActive     Boolean  @default(true) @map(\"is_active\")\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  tenant       Tenant        @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  items        Item[]\n  invoiceLines InvoiceLine[]\n\n  @@index([tenantId])\n  @@map(\"units\")\n}\n\n// ─── App User ─────────────────────────────────────────────────────────────────\nenum AuthProvider {\n  LOCAL\n  GOOGLE\n}\n\nmodel AppUser {\n  id           String       @id @default(uuid())\n  tenantId     String       @map(\"tenant_id\")\n  email        String\n  passwordHash String?      @map(\"password_hash\")\n  authProvider AuthProvider @default(LOCAL) @map(\"auth_provider\")\n  googleSub    String?      @unique @map(\"google_sub\")\n  fullName     String       @map(\"full_name\")\n  phone        String?\n  avatarUrl    String?      @map(\"avatar_url\")\n  isActive     Boolean      @default(true) @map(\"is_active\")\n  lastLoginAt  DateTime?    @map(\"last_login_at\")\n  createdAt    DateTime     @default(now()) @map(\"created_at\")\n  updatedAt    DateTime     @updatedAt @map(\"updated_at\")\n\n  tenant    Tenant     @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  userRoles UserRole[]\n\n  @@unique([tenantId, email])\n  @@index([tenantId])\n  @@map(\"app_users\")\n}\n\n// ─── Role ─────────────────────────────────────────────────────────────────────\nmodel Role {\n  id          String   @id @default(uuid())\n  tenantId    String   @map(\"tenant_id\")\n  name        Json     @db.JsonB // LocalizedString: { ar: string; en?: string }\n  description Json?    @db.JsonB // LocalizedString: { ar: string; en?: string }\n  isSystem    Boolean  @default(false) @map(\"is_system\")\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  tenant          Tenant           @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  userRoles       UserRole[]\n  rolePermissions RolePermission[]\n\n  // Note: unique on (tenantId, name->>'ar') enforced via expression index in migration SQL\n  @@index([tenantId])\n  @@map(\"roles\")\n}\n\n// ─── User Role (join table) ──────────────────────────────────────────────────\nmodel UserRole {\n  id        String   @id @default(uuid())\n  userId    String   @map(\"user_id\")\n  roleId    String   @map(\"role_id\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n\n  user AppUser @relation(fields: [userId], references: [id], onDelete: Cascade)\n  role Role    @relation(fields: [roleId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, roleId])\n  @@map(\"user_roles\")\n}\n\n// ─── Warehouse ────────────────────────────────────────────────────────────────\nmodel Warehouse {\n  id        String   @id @default(uuid())\n  tenantId  String   @map(\"tenant_id\")\n  code      String\n  name      Json     @db.JsonB\n  address   String?\n  isActive  Boolean  @default(true) @map(\"is_active\")\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  tenant         Tenant            @relation(fields: [tenantId], references: [id], onDelete: Cascade)\n  branches       BranchWarehouse[]\n  warehouseItems WarehouseItem[]\n  stockBalances  StockBalance[]\n  stockMovements StockMovement[]\n  invoices       Invoice[]\n  stockCounts    StockCount[]\n  posSettings    PosSetting[]\n\n  @@unique([tenantId, code])\n  @@index([tenantId])\n  @@map(\"warehouses\")\n}\n\n// ─── Warehouse Item ───────────────────────────────────────────────────────────\nmodel WarehouseItem {\n  id          String   @id @default(uuid())\n  tenantId    String   @map(\"tenant_id\")\n  warehouseId String   @map(\"warehouse_id\")\n  itemId      String   @map(\"item_id\")\n  minQuantity Decimal? @map(\"min_quantity\") @db.Decimal(18, 4)\n  maxQuantity Decimal? @map(\"max_quantity\") @db.Decimal(18, 4)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  warehouse Warehouse @relation(fields: [warehouseId], references: [id], onDelete: Cascade)\n  item      Item      @relation(fields: [itemId], references: [id], onDelete: Cascade)\n\n  @@unique([warehouseId, itemId])\n  @@index([tenantId])\n  @@map(\"warehouse_items\")\n}\n"
}

